// Overlay of core/framework/gen-src/android/bluetooth/BluetoothGatt.java (generated by tools/compat/genstubs.py:
// signatures and constants). It differs in being a GATT client of the phone's radio (megler.Bluetooth, Windows'
// GattSession and GATT services underneath), as Android 13's is:
//  - connect, disconnect and close; with autoConnect the connection is made whenever the device is in range, and again
//    after it drops, until disconnect (Windows' MaintainConnection);
//  - discoverServices, getServices and getService: the device's database, each attribute's instance id its handle;
//  - readCharacteristic, writeCharacteristic (Android 13's, which returns BluetoothStatusCodes, and the old one, which
//    sends the characteristic's value and write type), readDescriptor and writeDescriptor alike; one request at a time,
//    as Android's stack has it: a read while one is answered is refused (false), a write tried for a while and then
//    refused with ERROR_GATT_WRITE_REQUEST_BUSY. A write without response is answered (onCharacteristicWrite) once it is
//    sent, as Android answers it;
//  - setCharacteristicNotification, which lets the characteristic's notifications through to the app, and the write of
//    its Client Characteristic Configuration descriptor (0x2902), which subscribes to them at the device;
//  - requestMtu (onMtuChanged with what is in force: Windows negotiates its own as it connects, never more than asked),
//    readRemoteRssi (the last advertisement's, where Windows tells no connection's), requestConnectionPriority and the
//    PHY's calls (taken; Windows chooses), refresh (Android's hidden one, which apps reach by reflection: true, nothing is
//    kept to clear);
//  - a read or a write the device refuses for want of pairing (GATT_INSUFFICIENT_AUTHENTICATION or _ENCRYPTION) while it is
//    not bonded is done again once the radio has paired with it, as Android's stack pairs and tries again: the app hears
//    ACTION_BOND_STATE_CHANGED (and ACTION_PAIRING_REQUEST, for a PIN) and then the answer; a pairing that fails gives it
//    the device's refusal.
// The callbacks come on the Handler connectGatt was given, else in order on a thread of the framework's,
// "BluetoothGatt", as Android's come on a binder thread; Android 13's forms (onCharacteristicRead and
// onCharacteristicChanged with the value, onDescriptorRead with it), which BluetoothGattCallback hands to the old ones.
//
// Why. The stub's connectGatt was null: MeshCore's app (flutter_blue_plus) could not reach its radio.
package android.bluetooth;

import android.os.Handler;
import android.os.HandlerThread;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.UUID;

@SuppressWarnings({"unchecked", "rawtypes", "deprecation"})
public final class BluetoothGatt implements android.bluetooth.BluetoothProfile {
    private static final String TAG = "BluetoothGatt";
    /* What a write waits for while one is answered, as Android's (WRITE_CHARACTERISTIC_MAX_RETRIES, ..._TIME_TO_WAIT). */
    private static final int BUSY_TRIES = 5, BUSY_WAIT_MS = 10;

    /* The app's GATT clients by the core's number. */
    private static final HashMap<Integer, BluetoothGatt> sByConn = new HashMap<>();
    private static Handler sThread;

    private final BluetoothDevice mDevice;
    private final BluetoothGattCallback mCallback;
    private final Handler mHandler;
    private int mConn;
    private int mState = STATE_DISCONNECTED;
    private boolean mClosed;
    private final ArrayList<BluetoothGattService> mServices = new ArrayList<>();
    private final HashMap<Integer, BluetoothGattCharacteristic> mCharacteristics = new HashMap<>();
    private final HashMap<Integer, BluetoothGattDescriptor> mDescriptors = new HashMap<>();
    private final HashSet<Integer> mNotified = new HashSet<>();
    /* The request the device answers next, or null; and whether it waits for the radio to pair first. */
    private Request mRequest;
    private boolean mAwaitingBond;

    /** A read or a write sent, to know its answer by and to send again after a pairing. */
    private static final class Request {
        final boolean read;
        final int handle, type;
        final byte[] value;
        boolean retried;

        Request(boolean read, int handle, byte[] value, int type) {
            this.read = read;
            this.handle = handle;
            this.value = value;
            this.type = type;
        }
    }

    private BluetoothGatt(BluetoothDevice device, BluetoothGattCallback callback, Handler handler) {
        mDevice = device;
        mCallback = callback;
        mHandler = handler;
    }
    protected BluetoothGatt() { this(null, null, null); }

    /** BluetoothDevice.connectGatt: a client, connecting; null when there is no radio or it is off. */
    static BluetoothGatt meglerConnect(BluetoothDevice device, BluetoothGattCallback callback, boolean autoConnect, Handler handler) {
        if (megler.Bluetooth.state() != megler.Bluetooth.RADIO_ON) return null;
        BluetoothGatt g = new BluetoothGatt(device, callback, handler);
        synchronized (g) {
            g.mState = STATE_CONNECTING;
            // (Known by its number before the radio can answer for it.)
            synchronized (sByConn) {
                g.mConn = megler.Bluetooth.connect(device.meglerBits(), device.meglerType(), autoConnect, 0);
                if (g.mConn == 0) return null;
                sByConn.put(g.mConn, g);
            }
        }
        return g;
    }

    /** Where the callbacks run: the app's Handler, else the framework's thread for them. */
    private void post(Runnable r) {
        if (mHandler != null) {
            mHandler.post(r);
            return;
        }
        synchronized (BluetoothGatt.class) {
            if (sThread == null) {
                HandlerThread t = new HandlerThread("BluetoothGatt");
                t.setDaemon(true);
                t.start();
                sThread = new Handler(t.getLooper());
            }
        }
        sThread.post(r);
    }

    public BluetoothDevice getDevice() { return mDevice; }

    /** The connection made again (after it dropped, or after disconnect): whenever the device is in range, as Android's. */
    public boolean connect() {
        synchronized (this) {
            if (mClosed) return false;
            if (mState == STATE_CONNECTED || mState == STATE_CONNECTING) return true;
            mState = STATE_CONNECTING;
        }
        synchronized (sByConn) {
            int conn = megler.Bluetooth.connect(mDevice.meglerBits(), mDevice.meglerType(), true, mConn);
            if (conn == 0) {
                synchronized (this) { mState = STATE_DISCONNECTED; }
                return false;
            }
            // (The same number, as the core keeps it while the client is open; another is taken as it is.)
            if (conn != mConn) {
                sByConn.remove(mConn);
                mConn = conn;
                sByConn.put(conn, this);
            }
        }
        return true;
    }

    public void disconnect() {
        synchronized (this) {
            if (mClosed) return;
            if (mState == STATE_CONNECTED) mState = STATE_DISCONNECTING;
        }
        megler.Bluetooth.disconnect(mConn, false);
    }

    /** The client gone: disconnected if it was not, and no callback after this. */
    public void close() {
        synchronized (this) {
            if (mClosed) return;
            mClosed = true;
            mState = STATE_DISCONNECTED;
            mRequest = null;
        }
        synchronized (sByConn) { sByConn.remove(mConn); }
        megler.Bluetooth.disconnect(mConn, true);
    }

    public boolean discoverServices() {
        synchronized (this) {
            if (mClosed || mState != STATE_CONNECTED) return false;
        }
        return megler.Bluetooth.discover(mConn);
    }
    public boolean discoverServiceByUuid(UUID uuid) { return discoverServices(); }

    public List<BluetoothGattService> getServices() {
        synchronized (this) { return new ArrayList<>(mServices); }
    }
    public BluetoothGattService getService(UUID uuid) {
        synchronized (this) {
            for (BluetoothGattService s : mServices)
                if (s.getUuid().equals(uuid)) return s;
        }
        return null;
    }

    /** The one request at a time, taken: false while another is answered. */
    private synchronized boolean take(Request r) {
        if (mClosed || mState != STATE_CONNECTED || mRequest != null) return false;
        mRequest = r;
        return true;
    }
    private synchronized void drop(Request r) {
        if (mRequest == r) mRequest = null;
    }
    private synchronized boolean connected() { return !mClosed && mState == STATE_CONNECTED; }

    public boolean readCharacteristic(BluetoothGattCharacteristic c) {
        if (c == null || (c.getProperties() & BluetoothGattCharacteristic.PROPERTY_READ) == 0) return false;
        Request r = new Request(true, c.getInstanceId(), null, 0);
        if (!take(r)) return false;
        if (megler.Bluetooth.read(mConn, r.handle)) return true;
        drop(r);
        return false;
    }
    public boolean readUsingCharacteristicUuid(UUID uuid, int startHandle, int endHandle) { return false; }

    /** The old form: the characteristic's own value and write type. */
    public boolean writeCharacteristic(BluetoothGattCharacteristic c) {
        if (c == null || c.getValue() == null) return false;
        return writeCharacteristic(c, c.getValue(), c.getWriteType()) == BluetoothStatusCodes.SUCCESS;
    }

    /** Android 13's: BluetoothStatusCodes.SUCCESS when it is sent, ERROR_GATT_WRITE_REQUEST_BUSY while another is answered. */
    public int writeCharacteristic(BluetoothGattCharacteristic c, byte[] value, int writeType) {
        if (c == null) throw new IllegalArgumentException("characteristic must not be null");
        if (value == null) throw new IllegalArgumentException("value must not be null");
        if ((c.getProperties() & (BluetoothGattCharacteristic.PROPERTY_WRITE | BluetoothGattCharacteristic.PROPERTY_WRITE_NO_RESPONSE)) == 0)
            return BluetoothStatusCodes.ERROR_GATT_WRITE_NOT_ALLOWED;
        int type = writeType == BluetoothGattCharacteristic.WRITE_TYPE_NO_RESPONSE ? megler.Bluetooth.WRITE_COMMAND
                   : writeType == BluetoothGattCharacteristic.WRITE_TYPE_SIGNED  ? megler.Bluetooth.WRITE_SIGNED
                                                                                  : megler.Bluetooth.WRITE_REQUEST;
        return write(new Request(false, c.getInstanceId(), value.clone(), type));
    }

    public boolean readDescriptor(BluetoothGattDescriptor d) {
        if (d == null) return false;
        Request r = new Request(true, d.getInstanceId(), null, 0);
        if (!take(r)) return false;
        if (megler.Bluetooth.read(mConn, r.handle)) return true;
        drop(r);
        return false;
    }

    public boolean writeDescriptor(BluetoothGattDescriptor d) {
        return d != null && d.getValue() != null && writeDescriptor(d, d.getValue()) == BluetoothStatusCodes.SUCCESS;
    }

    public int writeDescriptor(BluetoothGattDescriptor d, byte[] value) {
        if (d == null) throw new IllegalArgumentException("descriptor must not be null");
        if (value == null) throw new IllegalArgumentException("value must not be null");
        return write(new Request(false, d.getInstanceId(), value.clone(), megler.Bluetooth.WRITE_REQUEST));
    }

    private int write(Request r) {
        if (!connected()) return BluetoothStatusCodes.ERROR_DEVICE_NOT_CONNECTED;
        for (int i = 0; !take(r); i++) {
            if (i == BUSY_TRIES || !connected()) return connected() ? BluetoothStatusCodes.ERROR_GATT_WRITE_REQUEST_BUSY : BluetoothStatusCodes.ERROR_DEVICE_NOT_CONNECTED;
            try {
                Thread.sleep(BUSY_WAIT_MS);
            } catch (InterruptedException e) {
                return BluetoothStatusCodes.ERROR_GATT_WRITE_REQUEST_BUSY;
            }
        }
        if (megler.Bluetooth.write(mConn, r.handle, r.value, r.type)) return BluetoothStatusCodes.SUCCESS;
        drop(r);
        return BluetoothStatusCodes.ERROR_UNKNOWN;
    }

    /** Lets the characteristic's notifications and indications through to the app (the device is told by its 0x2902 descriptor). */
    public boolean setCharacteristicNotification(BluetoothGattCharacteristic c, boolean enable) {
        if (c == null) return false;
        synchronized (this) {
            if (mClosed) return false;
            if (enable) mNotified.add(c.getInstanceId());
            else mNotified.remove(c.getInstanceId());
        }
        return true;
    }

    public boolean requestMtu(int mtu) { return connected() && megler.Bluetooth.mtu(mConn, mtu); }
    public boolean readRemoteRssi() { return connected() && megler.Bluetooth.rssi(mConn); }
    public boolean requestConnectionPriority(int priority) {
        if (priority < CONNECTION_PRIORITY_BALANCED || priority > CONNECTION_PRIORITY_DCK) throw new IllegalArgumentException("connectionPriority not within valid range");
        return connected();
    }
    public boolean requestLeConnectionUpdate(int minInterval, int maxInterval, int latency, int timeout, int minCe, int maxCe) { return connected(); }
    public void setPreferredPhy(int txPhy, int rxPhy, int options) {
        if (!connected()) return;
        post(() -> mCallback.onPhyUpdate(this, BluetoothDevice.PHY_LE_1M, BluetoothDevice.PHY_LE_1M, GATT_SUCCESS));
    }
    public void readPhy() {
        if (!connected()) return;
        post(() -> mCallback.onPhyRead(this, BluetoothDevice.PHY_LE_1M, BluetoothDevice.PHY_LE_1M, GATT_SUCCESS));
    }
    public boolean beginReliableWrite() { return false; }
    public boolean executeReliableWrite() { return false; }
    public void abortReliableWrite() {}
    public void abortReliableWrite(BluetoothDevice device) {}
    /** (Android's hidden cache flush: every discovery here asks the device afresh.) */
    public boolean refresh() { return !mClosed; }

    public int getConnectionState(BluetoothDevice device) { throw new UnsupportedOperationException("Use BluetoothManager#getConnectionState instead."); }
    public List getConnectedDevices() { throw new UnsupportedOperationException("Use BluetoothManager#getConnectedDevices instead."); }
    public List getDevicesMatchingConnectionStates(int[] states) { throw new UnsupportedOperationException("Use BluetoothManager#getDevicesMatchingConnectionStates instead."); }

    /* ------------------------------------------------------------------ the radio's events (megler.Bluetooth's thread) */

    /** An event of a connection: to its client. */
    public static void meglerEvent(int kind, int conn, int status, int handle, int value, byte[] data, int[] attrs, byte[] uuids) {
        BluetoothGatt g;
        synchronized (sByConn) { g = sByConn.get(conn); }
        if (g != null) g.event(kind, status, handle, value, data, attrs, uuids);
    }

    /** A device's bond changed: what its clients sent again for want of pairing, sent again or refused. */
    static void meglerBonded(long address, int state) {
        ArrayList<BluetoothGatt> all;
        synchronized (sByConn) { all = new ArrayList<>(sByConn.values()); }
        for (BluetoothGatt g : all)
            if (g.mDevice.meglerBits() == address) g.bonded(state);
    }

    private void bonded(int state) {
        Request r;
        synchronized (this) {
            if (!mAwaitingBond || state == BluetoothDevice.BOND_BONDING) return;
            mAwaitingBond = false;
            r = mRequest;
        }
        if (r == null) return;
        if (state == BluetoothDevice.BOND_BONDED && (r.read ? megler.Bluetooth.read(mConn, r.handle) : megler.Bluetooth.write(mConn, r.handle, r.value, r.type))) return;
        // (The pairing failed: the device's refusal is the answer.)
        answer(r, GATT_INSUFFICIENT_AUTHENTICATION, null);
    }

    private void event(int kind, final int status, int handle, final int value, final byte[] data, int[] attrs, byte[] uuids) {
        switch (kind) {
        case megler.Bluetooth.EVENT_CONNECTION: {
            final int now = value != 0 ? STATE_CONNECTED : STATE_DISCONNECTED;
            int before;
            synchronized (this) {
                if (mClosed) return;
                before = mState;
                mState = now;
                if (now == STATE_DISCONNECTED) {
                    mRequest = null;
                    mAwaitingBond = false;
                }
            }
            // (A disconnection of a client that was not connecting nor connected says nothing new.)
            if (before == STATE_DISCONNECTED && now == STATE_DISCONNECTED) return;
            post(() -> { if (!mClosed) mCallback.onConnectionStateChange(this, status, now); });
            return;
        }
        case megler.Bluetooth.EVENT_SERVICES:
            services(attrs, uuids);
            post(() -> { if (!mClosed) mCallback.onServicesDiscovered(this, status); });
            return;
        case megler.Bluetooth.EVENT_READ:
        case megler.Bluetooth.EVENT_WRITTEN: {
            Request r;
            boolean pair = false;
            synchronized (this) {
                r = mRequest;
                if (r == null || r.handle != handle) return;
                // The device wants pairing first: as Android's stack does, the radio pairs, and the request is sent again.
                if ((status == GATT_INSUFFICIENT_AUTHENTICATION || status == GATT_INSUFFICIENT_ENCRYPTION) && !r.retried
                    && megler.Bluetooth.bondState(mDevice.meglerBits()) == BluetoothDevice.BOND_NONE) {
                    r.retried = true;
                    mAwaitingBond = true;
                    pair = true;
                }
            }
            if (pair) {
                android.util.Log.i(TAG, mDevice.getAddress() + " wants pairing for handle " + handle + ": pairing, then sending it again");
                if (megler.Bluetooth.bond(mDevice.meglerBits(), mDevice.meglerType(), true)) return;
                synchronized (this) { mAwaitingBond = false; }
            }
            answer(r, status, data);
            return;
        }
        case megler.Bluetooth.EVENT_CHANGED: {
            final BluetoothGattCharacteristic c;
            synchronized (this) {
                c = mCharacteristics.get(handle);
                if (c == null || !mNotified.contains(handle) || mClosed) return;
            }
            final byte[] v = data != null ? data : new byte[0];
            post(() -> {
                if (mClosed) return;
                c.setValue(v);
                mCallback.onCharacteristicChanged(this, c, v);
            });
            return;
        }
        case megler.Bluetooth.EVENT_MTU:
            post(() -> { if (!mClosed) mCallback.onMtuChanged(this, value, status); });
            return;
        case megler.Bluetooth.EVENT_RSSI:
            post(() -> { if (!mClosed) mCallback.onReadRemoteRssi(this, value, status); });
            return;
        default:
            return;
        }
    }

    /** The answer to the request: the next may be sent, and the app hears this one's. */
    private void answer(Request r, final int status, byte[] data) {
        final BluetoothGattCharacteristic c;
        final BluetoothGattDescriptor d;
        synchronized (this) {
            if (mRequest != r) return;
            mRequest = null;
            c = mCharacteristics.get(r.handle);
            d = c == null ? mDescriptors.get(r.handle) : null;
        }
        final byte[] v = data != null ? data : new byte[0];
        if (r.read) {
            if (c != null) post(() -> {
                if (mClosed) return;
                if (status == GATT_SUCCESS) c.setValue(v);
                mCallback.onCharacteristicRead(this, c, v, status);
            });
            else if (d != null) post(() -> {
                if (mClosed) return;
                if (status == GATT_SUCCESS) d.setValue(v);
                mCallback.onDescriptorRead(this, d, status, v);
            });
        } else {
            if (c != null) post(() -> { if (!mClosed) mCallback.onCharacteristicWrite(this, c, status); });
            else if (d != null) post(() -> {
                if (mClosed) return;
                if (status == GATT_SUCCESS) d.setValue(r.value);
                mCallback.onDescriptorWrite(this, d, status);
            });
        }
    }

    /** The device's database as the radio found it: Android's services, characteristics and descriptors of it. */
    private void services(int[] attrs, byte[] uuids) {
        ArrayList<BluetoothGattService> list = new ArrayList<>();
        HashMap<Integer, BluetoothGattCharacteristic> chars = new HashMap<>();
        HashMap<Integer, BluetoothGattDescriptor> descs = new HashMap<>();
        ArrayList<Object[]> includes = new ArrayList<>();
        BluetoothGattService service = null;
        BluetoothGattCharacteristic characteristic = null;
        int n = attrs != null && uuids != null ? Math.min(attrs.length / 3, uuids.length / 16) : 0;
        for (int i = 0; i < n; i++) {
            int kind = attrs[i * 3], handle = attrs[i * 3 + 1], props = attrs[i * 3 + 2];
            UUID uuid = uuidAt(uuids, i * 16);
            switch (kind) {
            case megler.Bluetooth.ATTR_SERVICE:
            case megler.Bluetooth.ATTR_SECONDARY:
                service = new BluetoothGattService(mDevice, uuid, handle,
                                                   kind == megler.Bluetooth.ATTR_SERVICE ? BluetoothGattService.SERVICE_TYPE_PRIMARY : BluetoothGattService.SERVICE_TYPE_SECONDARY);
                list.add(service);
                characteristic = null;
                break;
            case megler.Bluetooth.ATTR_INCLUDED:
                if (service != null) includes.add(new Object[] { service, handle, uuid });
                break;
            case megler.Bluetooth.ATTR_CHARACTERISTIC:
                if (service == null) break;
                characteristic = new BluetoothGattCharacteristic(service, uuid, handle, props & 0xff, 0);
                service.addCharacteristic(characteristic);
                chars.put(handle, characteristic);
                break;
            case megler.Bluetooth.ATTR_DESCRIPTOR:
                if (characteristic == null) break;
                BluetoothGattDescriptor descriptor = new BluetoothGattDescriptor(characteristic, uuid, handle, 0);
                characteristic.addDescriptor(descriptor);
                descs.put(handle, descriptor);
                break;
            default:
                break;
            }
        }
        // (An included service is the one of that handle, as Android links them.)
        for (Object[] inc : includes) {
            BluetoothGattService into = (BluetoothGattService) inc[0], found = null;
            for (BluetoothGattService s : list)
                if (s.getInstanceId() == (Integer) inc[1]) found = s;
            if (found == null) found = new BluetoothGattService(mDevice, (UUID) inc[2], (Integer) inc[1], BluetoothGattService.SERVICE_TYPE_SECONDARY);
            into.addIncludedService(found);
        }
        synchronized (this) {
            mServices.clear();
            mServices.addAll(list);
            mCharacteristics.clear();
            mCharacteristics.putAll(chars);
            mDescriptors.clear();
            mDescriptors.putAll(descs);
        }
    }

    private static UUID uuidAt(byte[] b, int at) {
        long msb = 0, lsb = 0;
        for (int i = 0; i < 8; i++) msb = msb << 8 | (b[at + i] & 0xff);
        for (int i = 8; i < 16; i++) lsb = lsb << 8 | (b[at + i] & 0xff);
        return new UUID(msb, lsb);
    }
    private final java.util.HashMap<String, Object> meglerProps = new java.util.HashMap<>();
    public static final int CONNECTION_PRIORITY_BALANCED = 0;
    public static final int CONNECTION_PRIORITY_DCK = 3;
    public static final int CONNECTION_PRIORITY_HIGH = 1;
    public static final int CONNECTION_PRIORITY_LOW_POWER = 2;
    public static final int GATT_CONNECTION_CONGESTED = 143;
    public static final int GATT_CONNECTION_TIMEOUT = 147;
    public static final int GATT_FAILURE = 257;
    public static final int GATT_INSUFFICIENT_AUTHENTICATION = 5;
    public static final int GATT_INSUFFICIENT_AUTHORIZATION = 8;
    public static final int GATT_INSUFFICIENT_ENCRYPTION = 15;
    public static final int GATT_INVALID_ATTRIBUTE_LENGTH = 13;
    public static final int GATT_INVALID_OFFSET = 7;
    public static final int GATT_READ_NOT_PERMITTED = 2;
    public static final int GATT_REQUEST_NOT_SUPPORTED = 6;
    public static final int GATT_SUCCESS = 0;
    public static final int GATT_WRITE_NOT_PERMITTED = 3;
    public static final int SUBRATE_MODE_BALANCED = 2;
    public static final int SUBRATE_MODE_HIGH = 3;
    public static final int SUBRATE_MODE_LOW = 1;
    public static final int SUBRATE_MODE_NOT_UPDATED = 255;
    public static final int SUBRATE_MODE_OFF = 0;
    public static final int SUBRATE_MODE_SYSTEM_UPDATE = 99;
    public android.bluetooth.BluetoothAdapter getAdapter() { return (android.bluetooth.BluetoothAdapter) meglerProps.get("Adapter"); }
    public void onServiceConnected(android.os.IBinder p0) {}
    public void onServiceDisconnected() {}
    public int requestSubrateMode(int p0) { return 0; }
}
